/**
 * TypeScript mirror of `packages/core/API.md` (Phase 1 contract).
 * The real module is generated by wasm-pack into `src/core-wasm/`; the mock in
 * `mock.ts` implements the same shapes so the UI works before the core is built.
 */

export interface RenderedPage {
  readonly width: number;
  readonly height: number;
  /** RGBA8, premultiplied alpha over white, `width * height * 4` bytes. */
  readonly rgba: Uint8Array;
  free(): void;
}

export type TextDirection = 'rtl' | 'ltr';

export interface TextLine {
  readonly text: string;
  /** Page-space geometry in points, origin at the top-left corner after /Rotate. */
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly direction: TextDirection;
  free(): void;
}

export type TextAlignment = 'start' | 'end' | 'center' | 'justify';

/** One editable paragraph, in the same device space as `TextLine`. */
export interface ParagraphInfo {
  /** Index of the paragraph on its page; the handle for `replace_paragraph`. */
  readonly index: number;
  readonly text: string;
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly direction: TextDirection;
  readonly alignment: TextAlignment;
  readonly font_size: number;
  readonly line_count: number;
  free(): void;
}

export interface CoreDocument {
  page_count(): number;
  /** `[width_pt, height_pt]` after /Rotate. */
  page_size(index: number): Float32Array;
  render_page(index: number, scale: number): RenderedPage;
  /** Logical-order text, lines joined by "\n". */
  extract_text(index: number): string;
  text_lines(index: number): TextLine[];
  /** Page indices matching the query (Arabic-aware normalization). */
  search(query: string): Uint32Array;
  /** JSON: {title, author, producer, creator, pages, encrypted}. */
  metadata(): string;

  /* Editing (Phase 2). */

  /** Editable paragraphs of a page, in device space. */
  paragraphs(index: number): ParagraphInfo[];
  /** Reflows and reshapes the paragraph; returns JSON `{lines_drawn, font_substituted}`. */
  replace_paragraph(index: number, para: number, text: string, font: Uint8Array): string;
  /** Edited bytes: an incremental update over the original wherever possible. */
  save(): Uint8Array;
  free(): void;
}

export interface CoreModule {
  version(): string;
  Document: {
    open(bytes: Uint8Array, password?: string): CoreDocument;
  };
}

/** `native` is the desktop host: `warraq-core` linked into Tauri, not WASM. */
export type CoreKind = 'wasm' | 'mock' | 'native';

export interface CoreStatus {
  kind: CoreKind;
  version: string;
  /** Rasterizer actually in use, e.g. "pdfium+hayro"; native host only. */
  engine?: string;
}

export interface DocumentMetadata {
  title?: string;
  author?: string;
  producer?: string;
  creator?: string;
  pages: number;
  encrypted: boolean;
}

/** Stable error codes from API.md plus the ones the client adds. */
export type CoreErrorCode =
  | 'E_PARSE'
  | 'E_PASSWORD'
  | 'E_RENDER'
  | 'E_NOT_FOUND'
  | 'E_WORKER'
  | 'E_UNKNOWN';

export interface CoreError {
  code: CoreErrorCode | string;
  message: string;
}

/* Plain-data twins that can cross the worker boundary (structured clone). */

export interface TextLineData {
  text: string;
  x: number;
  y: number;
  width: number;
  height: number;
  direction: TextDirection;
}

export interface ParagraphData {
  index: number;
  text: string;
  x: number;
  y: number;
  width: number;
  height: number;
  direction: TextDirection;
  alignment: TextAlignment;
  fontSize: number;
  lineCount: number;
}

/** Parsed result of `replace_paragraph`. */
export interface ReplaceParagraphResult {
  /** The text had to be shrunk to fit the paragraph's box. */
  shrunk?: boolean;
  /** It still runs past the box: the user should be warned. */
  overflowed?: boolean;
  linesDrawn: number;
  /**
   * The original face could not be reused and a bundled one was embedded.
   * Brief §15.5: the user is always told, never silently corrupted.
   */
  fontSubstituted: boolean;
}

export interface RenderedPageData {
  width: number;
  height: number;
  /** Owns its buffer, so it can be transferred and wrapped in `ImageData`. */
  rgba: Uint8ClampedArray<ArrayBuffer>;
}

export type PageSize = readonly [width: number, height: number];

export interface OpenedDocumentInfo {
  /** Handle id inside the worker. */
  doc: number;
  pageCount: number;
  pageSizes: PageSize[];
  metadata: DocumentMetadata;
}
